// ---------------------------------------------------------------------------
// Usage
// ---------------------------------------------------------------------------
static void printUsage(const char* argv0) {
    std::cerr
        << "Usage: " << argv0 << " [options] <input.jsx> [<input2.jsx> ...]\n"
        << "       " << argv0 << " [options] --out-dir <dir> <input.jsx> ...\n"
        << "\nOptions:\n"
        << "  -o <file>        Write output to file (single-file mode)\n"
        << "  --out-dir <dir>  Output directory for batch mode\n"
        << "  --pragma <name>  JSX pragma: react (default), h, jsx, auto\n"
        << "  --dev            Emit __source/__self dev props\n"
        << "  --recover        Collect multiple errors instead of stopping on first\n"
        << "  -h, --help       Show this help\n";
}

// ---------------------------------------------------------------------------
// File I/O
// ---------------------------------------------------------------------------
static std::string readFile(const std::string& path) {
    std::ifstream f(path);
    if (!f) {
        std::cerr << "error: cannot open '" << path << "'\n";
        std::exit(1);
    }
    std::ostringstream ss;
    ss << f.rdbuf();
    return ss.str();
}

static bool writeFile(const std::string& path, const std::string& content) {
    std::ofstream out(path);
    if (!out) {
        std::cerr << "error: cannot write to '" << path << "'\n";
        return false;
    }
    out << content;
    return true;
}

// ---------------------------------------------------------------------------
// Derive output path for batch mode: replaces extension with .js
// ---------------------------------------------------------------------------
static std::string batchOutputPath(const std::string& outDir,
                                   const std::string& inputPath) {
    fs::path p(inputPath);
    fs::path out = fs::path(outDir) / p.filename().replace_extension(".js");
    return out.string();
}

// ---------------------------------------------------------------------------
// Transpile one file; returns true on success
// ---------------------------------------------------------------------------
static bool transpileFile(const std::string& inputPath,
                          const std::string& outputPath,
                          const CodeGenOptions& opts,
                          bool recoverMode) {
    std::string source = readFile(inputPath);

    try {
        Lexer lexer(source);
        auto tokens = lexer.tokenize();

        ErrorCollector errors;
        Parser parser(std::move(tokens), recoverMode ? &errors : nullptr);
        auto ast = parser.parse();

        if (recoverMode && errors.hasErrors()) {
            errors.dump(inputPath);
            return false;
        }

        CodeGen gen(opts);
        std::string output = gen.generate(*ast, inputPath);

        if (outputPath.empty()) {
            std::cout << output;
        } else {
            if (!writeFile(outputPath, output)) return false;
        }

    } catch (const LexError& e) {
        std::cerr << inputPath << ":" << e.line << ":" << e.col
                  << ": lex error: " << e.what() << "\n";
        return false;
    } catch (const ParseError& e) {
        std::cerr << inputPath << ":" << e.line << ":" << e.col
                  << ": parse error: " << e.what() << "\n";
        return false;
    } catch (const CodeGenError& e) {
        std::cerr << inputPath << ": codegen error: " << e.what() << "\n";
        return false;
    } catch (const std::exception& e) {
        std::cerr << inputPath << ": error: " << e.what() << "\n";
        return false;
    }
    return true;
}

// ---------------------------------------------------------------------------
// main
// ---------------------------------------------------------------------------
int main(int argc, char** argv) {
    std::vector<std::string> inputs;
    std::string outputPath;
    std::string outDir;
    bool recoverMode = false;
    CodeGenOptions opts;

    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];

        if (arg == "-h" || arg == "--help") {
            printUsage(argv[0]);
            return 0;
        } else if (arg == "-o") {
            if (++i >= argc) { std::cerr << "error: -o requires a filename\n"; return 1; }
            outputPath = argv[i];
        } else if (arg == "--out-dir") {
            if (++i >= argc) { std::cerr << "error: --out-dir requires a directory\n"; return 1; }
            outDir = argv[i];
        } else if (arg == "--pragma") {
            if (++i >= argc) { std::cerr << "error: --pragma requires a value\n"; return 1; }
            std::string p = argv[i];
            if      (p == "react") opts.pragma = JSXPragma::React;
            else if (p == "h")     opts.pragma = JSXPragma::H;
            else if (p == "jsx")   opts.pragma = JSXPragma::JSX;
            else if (p == "auto")  opts.pragma = JSXPragma::AutoImport;
            else {
                std::cerr << "error: unknown pragma '" << p
                          << "' (use: react, h, jsx, auto)\n";
                return 1;
            }
        } else if (arg == "--dev") {
            opts.devMode = true;
        } else if (arg == "--recover") {
            recoverMode = true;
        } else if (arg[0] == '-') {
            std::cerr << "error: unknown option '" << arg << "'\n";
            printUsage(argv[0]);
            return 1;
        } else {
            inputs.push_back(arg);
        }
    }

    if (inputs.empty()) {
        printUsage(argv[0]);
        return 1;
    }

    // Batch mode with --out-dir
    if (!outDir.empty()) {
        // Create output directory if needed
        std::error_code ec;
        fs::create_directories(outDir, ec);
        if (ec) {
            std::cerr << "error: cannot create output dir '" << outDir
                      << "': " << ec.message() << "\n";
            return 1;
        }
        int failures = 0;
        for (const auto& inp : inputs) {
            std::string outp = batchOutputPath(outDir, inp);
            if (!transpileFile(inp, outp, opts, recoverMode)) ++failures;
        }
        return failures > 0 ? 1 : 0;
    }

    // Single-file mode
    if (inputs.size() > 1 && outputPath.empty()) {
        // Multiple inputs but no --out-dir: error
        std::cerr << "error: multiple input files require --out-dir\n";
        return 1;
    }

    if (!transpileFile(inputs[0], outputPath, opts, recoverMode)) return 1;
    return 0;
}

