// ---------------------------------------------------------------------------
// Fixed-size thread pool.
// Submit work items via enqueue(); call waitAll() to block until all pending
// tasks have finished.  The pool shuts down cleanly on destruction.
// ---------------------------------------------------------------------------
class ThreadPool {
public:
    explicit ThreadPool(size_t numThreads);
    ~ThreadPool();

    // Submit a task.  Returns immediately.
    void enqueue(std::function<void()> task);

    // Block until the work queue is empty and all workers are idle.
    void waitAll();

private:
    std::vector<std::thread>          workers_;
    std::queue<std::function<void()>> tasks_;
    std::mutex                        mtx_;
    std::condition_variable           cv_;
    std::condition_variable           cvDone_;
    size_t                            busy_ = 0;
    bool                              stop_ = false;

    void workerLoop();
};

#include "threadpool.h"

ThreadPool::ThreadPool(size_t numThreads) {
    for (size_t i = 0; i < numThreads; ++i)
        workers_.emplace_back([this] { workerLoop(); });
}

ThreadPool::~ThreadPool() {
    {
        std::unique_lock<std::mutex> lk(mtx_);
        stop_ = true;
    }
    cv_.notify_all();
    for (auto& t : workers_) t.join();
}

void ThreadPool::enqueue(std::function<void()> task) {
    {
        std::unique_lock<std::mutex> lk(mtx_);
        tasks_.push(std::move(task));
    }
    cv_.notify_one();
}

void ThreadPool::waitAll() {
    std::unique_lock<std::mutex> lk(mtx_);
    cvDone_.wait(lk, [this] { return tasks_.empty() && busy_ == 0; });
}

void ThreadPool::workerLoop() {
    while (true) {
        std::function<void()> task;
        {
            std::unique_lock<std::mutex> lk(mtx_);
            cv_.wait(lk, [this] { return stop_ || !tasks_.empty(); });
            if (stop_ && tasks_.empty()) return;
            task = std::move(tasks_.front());
            tasks_.pop();
            ++busy_;
        }
        task();
        {
            std::unique_lock<std::mutex> lk(mtx_);
            --busy_;
            if (tasks_.empty() && busy_ == 0)
                cvDone_.notify_all();
        }
    }
}

