namespace fs = std::filesystem;

// ---------------------------------------------------------------------------
// BatchOptions — configuration for a directory batch run
// ---------------------------------------------------------------------------
struct BatchOptions {
    fs::path       srcDir;
    fs::path       outDir;
    CodeGenOptions codegenOpts;
    bool           noCopy  = false;   // skip plain .js passthrough
    bool           verbose = false;   // print src→dst for each file
    unsigned       threads = 0;       // 0 = hardware_concurrency
};

// ---------------------------------------------------------------------------
// BatchResult — aggregate outcome after processing all files
// ---------------------------------------------------------------------------
struct BatchResult {
    int transpiled = 0;
    int copied     = 0;
    int failed     = 0;
    int skipped    = 0;

    struct FileError {
        std::string path;
        std::string message;
    };
    std::vector<FileError> errors;

    bool ok() const { return failed == 0; }
};

// ---------------------------------------------------------------------------
// BatchEngine — scans srcDir recursively, transpiles .jsx, copies .js
// ---------------------------------------------------------------------------
class BatchEngine {
public:
    explicit BatchEngine(BatchOptions opts);

    // Run one pass.  Returns aggregate result.
    BatchResult run();

    // Process a single file (used by both run() and the watcher).
    // Returns true on success.
    bool processFile(const fs::path& srcFile, BatchResult& result);

private:
    BatchOptions opts_;
    std::mutex   resultMtx_; // guards BatchResult from multiple threads

    fs::path outputPath(const fs::path& srcFile) const;
    bool transpileFile(const fs::path& src, const fs::path& dst,
                       BatchResult& result);
    bool copyFile(const fs::path& src, const fs::path& dst,
                  BatchResult& result);
    void log(const std::string& msg) const;
};

#include "batch.h"
#include "threadpool.h"
#include "lexer.h"
#include "parser.h"
#include "codegen.h"
#include "diagnostics.h"

#include <fstream>
#include <iostream>
#include <sstream>

// ---------------------------------------------------------------------------
// Construction
// ---------------------------------------------------------------------------
BatchEngine::BatchEngine(BatchOptions opts) : opts_(std::move(opts)) {}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
void BatchEngine::log(const std::string& msg) const {
    if (opts_.verbose)
        std::cout << msg << "\n";
}

// Compute the output path for a given source file:
//   srcDir/a/b/Foo.jsx  ->  outDir/a/b/Foo.js
//   srcDir/a/b/bar.js   ->  outDir/a/b/bar.js
fs::path BatchEngine::outputPath(const fs::path& srcFile) const {
    fs::path rel = fs::relative(srcFile, opts_.srcDir);
    fs::path dst = opts_.outDir / rel;
    if (dst.extension() == ".jsx")
        dst.replace_extension(".js");
    return dst;
}

// ---------------------------------------------------------------------------
// Transpile one .jsx file
// ---------------------------------------------------------------------------
bool BatchEngine::transpileFile(const fs::path& src, const fs::path& dst,
                                BatchResult& result) {
    // Read source
    std::ifstream in(src);
    if (!in) {
        std::unique_lock<std::mutex> lk(resultMtx_);
        result.errors.push_back({ src.string(), "cannot open for reading" });
        ++result.failed;
        return false;
    }
    std::ostringstream ss;
    ss << in.rdbuf();
    std::string source = ss.str();

    // Transpile
    std::string output;
    try {
        Lexer lexer(source);
        auto tokens = lexer.tokenize();
        Parser parser(std::move(tokens));
        auto ast = parser.parse();
        CodeGen gen(opts_.codegenOpts);
        output = gen.generate(*ast, src.string());
    } catch (const LexError& e) {
        std::string msg = src.string() + ":" + std::to_string(e.line) + ":"
                        + std::to_string(e.col) + ": lex error: " + e.what();
        std::unique_lock<std::mutex> lk(resultMtx_);
        result.errors.push_back({ src.string(), msg });
        ++result.failed;
        return false;
    } catch (const ParseError& e) {
        std::string msg = src.string() + ":" + std::to_string(e.line) + ":"
                        + std::to_string(e.col) + ": parse error: " + e.what();
        std::unique_lock<std::mutex> lk(resultMtx_);
        result.errors.push_back({ src.string(), msg });
        ++result.failed;
        return false;
    } catch (const std::exception& e) {
        std::string msg = src.string() + ": error: " + e.what();
        std::unique_lock<std::mutex> lk(resultMtx_);
        result.errors.push_back({ src.string(), msg });
        ++result.failed;
        return false;
    }

    // Ensure output directory exists
    std::error_code ec;
    fs::create_directories(dst.parent_path(), ec);
    if (ec) {
        std::unique_lock<std::mutex> lk(resultMtx_);
        result.errors.push_back({ src.string(),
            "cannot create directory " + dst.parent_path().string()
            + ": " + ec.message() });
        ++result.failed;
        return false;
    }

    // Write output
    std::ofstream out(dst);
    if (!out) {
        std::unique_lock<std::mutex> lk(resultMtx_);
        result.errors.push_back({ src.string(),
            "cannot write to " + dst.string() });
        ++result.failed;
        return false;
    }
    out << output;

    log("  " + src.string() + "  ->  " + dst.string());
    {
        std::unique_lock<std::mutex> lk(resultMtx_);
        ++result.transpiled;
    }
    return true;
}

// ---------------------------------------------------------------------------
// Copy one plain .js file
// ---------------------------------------------------------------------------
bool BatchEngine::copyFile(const fs::path& src, const fs::path& dst,
                           BatchResult& result) {
    std::error_code ec;
    fs::create_directories(dst.parent_path(), ec);
    if (ec) {
        std::unique_lock<std::mutex> lk(resultMtx_);
        result.errors.push_back({ src.string(),
            "cannot create directory " + dst.parent_path().string()
            + ": " + ec.message() });
        ++result.failed;
        return false;
    }

    fs::copy_file(src, dst, fs::copy_options::overwrite_existing, ec);
    if (ec) {
        std::unique_lock<std::mutex> lk(resultMtx_);
        result.errors.push_back({ src.string(),
            "copy failed: " + ec.message() });
        ++result.failed;
        return false;
    }

    log("  " + src.string() + "  =>  " + dst.string() + "  (copy)");
    {
        std::unique_lock<std::mutex> lk(resultMtx_);
        ++result.copied;
    }
    return true;
}

// ---------------------------------------------------------------------------
// Process one file (dispatch to transpile or copy)
// ---------------------------------------------------------------------------
bool BatchEngine::processFile(const fs::path& srcFile, BatchResult& result) {
    std::string ext = srcFile.extension().string();

    if (ext == ".jsx") {
        fs::path dst = outputPath(srcFile);
        return transpileFile(srcFile, dst, result);
    }

    if (ext == ".js") {
        if (opts_.noCopy) {
            std::unique_lock<std::mutex> lk(resultMtx_);
            ++result.skipped;
            return true;
        }
        fs::path dst = outputPath(srcFile);
        return copyFile(srcFile, dst, result);
    }

    // Unknown extension — skip silently
    std::unique_lock<std::mutex> lk(resultMtx_);
    ++result.skipped;
    return true;
}

// ---------------------------------------------------------------------------
// Run a full pass over srcDir
// ---------------------------------------------------------------------------
BatchResult BatchEngine::run() {
    BatchResult result;

    if (!fs::exists(opts_.srcDir)) {
        result.errors.push_back({ opts_.srcDir.string(), "source directory does not exist" });
        ++result.failed;
        return result;
    }

    // Collect all files first (recursive_directory_iterator is not thread-safe)
    std::vector<fs::path> files;
    for (const auto& entry : fs::recursive_directory_iterator(opts_.srcDir)) {
        if (entry.is_regular_file()) {
            std::string ext = entry.path().extension().string();
            if (ext == ".jsx" || ext == ".js")
                files.push_back(entry.path());
        }
    }

    if (files.empty()) return result;

    // Determine thread count
    unsigned hw = std::thread::hardware_concurrency();
    unsigned nThreads = opts_.threads > 0 ? opts_.threads
                      : (hw > 0 ? hw : 4);
    // Don't create more threads than files
    if (nThreads > static_cast<unsigned>(files.size()))
        nThreads = static_cast<unsigned>(files.size());

    if (nThreads <= 1) {
        // Single-threaded path — avoids lock overhead for small sets
        for (const auto& f : files)
            processFile(f, result);
    } else {
        ThreadPool pool(nThreads);
        for (const auto& f : files) {
            pool.enqueue([this, f, &result] {
                processFile(f, result);
            });
        }
        pool.waitAll();
    }

    return result;
}

