// ---------------------------------------------------------------------------
// Watcher — monitors a directory tree for changes and re-runs BatchEngine
//
// Strategy:
//   Windows : ReadDirectoryChangesW (native, low-latency)
//   Others  : polling every `pollIntervalMs` milliseconds
//
// Usage:
//   Watcher w(engine, verboseFlag);
//   w.watch(srcDir);   // blocks until stop() is called (e.g. Ctrl-C)
// ---------------------------------------------------------------------------
class Watcher {
public:
    explicit Watcher(BatchEngine& engine, bool verbose = false,
                     unsigned pollIntervalMs = 500);

    // Block until SIGINT / stop().
    void watch(const fs::path& srcDir);

    // Thread-safe: signal the watch loop to exit.
    void stop();

private:
    BatchEngine&  engine_;
    bool          verbose_;
    unsigned      pollMs_;
    std::atomic<bool> running_{true};

#if defined(_WIN32)
    void watchWindows(const fs::path& dir);
#endif
    void watchPolling(const fs::path& dir);

    // Map path -> last_write_time for change detection
    using TimeMap = std::unordered_map<std::string,
                                       fs::file_time_type>;
    TimeMap snapshot(const fs::path& dir) const;

    void handleChanged(const fs::path& srcFile);
};

#include "watcher.h"
#include <iostream>
#include <thread>
#include <chrono>

#if defined(_WIN32)
#  define WIN32_LEAN_AND_MEAN
#  define NOMINMAX
#  include <windows.h>
#endif

// ---------------------------------------------------------------------------
// Construction
// ---------------------------------------------------------------------------
Watcher::Watcher(BatchEngine& engine, bool verbose, unsigned pollIntervalMs)
    : engine_(engine), verbose_(verbose), pollMs_(pollIntervalMs) {}

void Watcher::stop() { running_ = false; }

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------
void Watcher::watch(const fs::path& srcDir) {
    running_ = true;
#if defined(_WIN32)
    watchWindows(srcDir);
#else
    watchPolling(srcDir);
#endif
}

// ---------------------------------------------------------------------------
// Handle a single changed file
// ---------------------------------------------------------------------------
void Watcher::handleChanged(const fs::path& srcFile) {
    std::string ext = srcFile.extension().string();
    if (ext != ".jsx" && ext != ".js") return;

    if (verbose_)
        std::cout << "[watch] changed: " << srcFile.string() << "\n";

    BatchResult r;
    engine_.processFile(srcFile, r);

    for (const auto& e : r.errors)
        std::cerr << e.message << "\n";
}

// ---------------------------------------------------------------------------
// Polling watcher (cross-platform fallback)
// ---------------------------------------------------------------------------
Watcher::TimeMap Watcher::snapshot(const fs::path& dir) const {
    TimeMap m;
    std::error_code ec;
    for (const auto& entry : fs::recursive_directory_iterator(dir, ec)) {
        if (ec) break;
        if (!entry.is_regular_file()) continue;
        std::string ext = entry.path().extension().string();
        if (ext != ".jsx" && ext != ".js") continue;
        auto t = fs::last_write_time(entry.path(), ec);
        if (!ec) m[entry.path().string()] = t;
    }
    return m;
}

void Watcher::watchPolling(const fs::path& srcDir) {
    std::cout << "[watch] polling " << srcDir.string()
              << " every " << pollMs_ << "ms  (Ctrl-C to stop)\n";

    TimeMap prev = snapshot(srcDir);

    while (running_) {
        std::this_thread::sleep_for(std::chrono::milliseconds(pollMs_));
        if (!running_) break;

        TimeMap cur = snapshot(srcDir);

        for (const auto& [path, t] : cur) {
            auto it = prev.find(path);
            if (it == prev.end() || it->second != t) {
                handleChanged(fs::path(path));
            }
        }
        prev = std::move(cur);
    }
}

// ---------------------------------------------------------------------------
// Windows-native watcher using ReadDirectoryChangesW
// ---------------------------------------------------------------------------
#if defined(_WIN32)
void Watcher::watchWindows(const fs::path& srcDir) {
    std::wstring wdir = srcDir.wstring();

    HANDLE hDir = CreateFileW(
        wdir.c_str(),
        FILE_LIST_DIRECTORY,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
        nullptr,
        OPEN_EXISTING,
        FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OVERLAPPED,
        nullptr
    );

    if (hDir == INVALID_HANDLE_VALUE) {
        std::cerr << "[watch] CreateFileW failed, falling back to polling\n";
        watchPolling(srcDir);
        return;
    }

    std::cout << "[watch] " << srcDir.string()
              << "  (Ctrl-C to stop)\n";

    // Buffer large enough for several notifications
    constexpr DWORD BUFSIZE = 65536;
    std::vector<BYTE> buf(BUFSIZE);
    OVERLAPPED ov{};
    ov.hEvent = CreateEvent(nullptr, TRUE, FALSE, nullptr);

    auto cleanup = [&] {
        CancelIo(hDir);
        CloseHandle(ov.hEvent);
        CloseHandle(hDir);
    };

    while (running_) {
        DWORD bytesRet = 0;
        ResetEvent(ov.hEvent);
        BOOL ok = ReadDirectoryChangesW(
            hDir,
            buf.data(), BUFSIZE,
            TRUE,  // watch subtree
            FILE_NOTIFY_CHANGE_LAST_WRITE | FILE_NOTIFY_CHANGE_FILE_NAME
            | FILE_NOTIFY_CHANGE_DIR_NAME,
            nullptr, &ov, nullptr
        );

        if (!ok && GetLastError() != ERROR_IO_PENDING) {
            std::cerr << "[watch] ReadDirectoryChangesW error, switching to polling\n";
            cleanup();
            watchPolling(srcDir);
            return;
        }

        // Wait up to pollMs_ so we can check running_ regularly
        DWORD waitRes = WaitForSingleObject(ov.hEvent,
                                            static_cast<DWORD>(pollMs_));
        if (!running_) break;
        if (waitRes == WAIT_TIMEOUT) continue;

        if (!GetOverlappedResult(hDir, &ov, &bytesRet, FALSE) || bytesRet == 0)
            continue;

        // Walk the notification records
        const BYTE* p = buf.data();
        while (true) {
            const auto* info = reinterpret_cast<const FILE_NOTIFY_INFORMATION*>(p);
            if (info->Action == FILE_ACTION_MODIFIED ||
                info->Action == FILE_ACTION_ADDED    ||
                info->Action == FILE_ACTION_RENAMED_NEW_NAME) {
                // FileName is a relative wide string, NOT null-terminated
                std::wstring rel(info->FileName,
                                 info->FileNameLength / sizeof(WCHAR));
                fs::path changed = srcDir / rel;
                handleChanged(changed);
            }
            if (info->NextEntryOffset == 0) break;
            p += info->NextEntryOffset;
        }
    }

    cleanup();
}
#endif

