// ---------------------------------------------------------------------------
// Global watcher pointer for signal handler
// ---------------------------------------------------------------------------
static Watcher* g_watcher = nullptr;

extern "C" void handleSignal(int) {
    if (g_watcher) g_watcher->stop();
}

// ---------------------------------------------------------------------------
// Usage
// ---------------------------------------------------------------------------
static void printUsage(const char* argv0) {
    std::cerr
        << "Usage:\n"
        << "  " << argv0 << " [options] <input.jsx>          # single file\n"
        << "  " << argv0 << " [options] --out-dir <dir> <files...>   # batch\n"
        << "  " << argv0 << " [options] <srcDir> --out-dir <dir>     # directory\n"
        << "\nOptions:\n"
        << "  -o <file>                  Output file (single-file mode)\n"
        << "  --out-dir <dir>            Output directory\n"
        << "  --pragma <name>            JSX pragma: react (default), h, jsx, auto\n"
        << "  --jsx-pragma <name>        Alias for --pragma\n"
        << "  --jsx-runtime <mode>       classic (default) | automatic (same as --pragma auto)\n"
        << "  --dev                      Emit __source/__self dev props\n"
        << "  --no-copy                  Skip .js passthrough in batch mode\n"
        << "  --verbose                  Print each file processed\n"
        << "  --watch                    Re-transpile on file changes (batch/dir mode)\n"
        << "  --threads <n>              Worker thread count (default: hw_concurrency)\n"
        << "  --recover                  Collect multiple errors before stopping\n"
        << "  -h, --help                 Show this help\n";
}

// ---------------------------------------------------------------------------
// File I/O helpers
// ---------------------------------------------------------------------------
static std::string readFile(const std::string& path) {
    std::ifstream f(path);
    if (!f) { std::cerr << "error: cannot open '" << path << "'\n"; std::exit(1); }
    std::ostringstream ss;
    ss << f.rdbuf();
    return ss.str();
}

static bool writeFile(const std::string& path, const std::string& content) {
    std::ofstream out(path);
    if (!out) { std::cerr << "error: cannot write '" << path << "'\n"; return false; }
    out << content;
    return true;
}

// ---------------------------------------------------------------------------
// Single-file transpile (original behaviour, kept intact)
// ---------------------------------------------------------------------------
static bool transpileSingle(const std::string& inputPath,
                            const std::string& outputPath,
                            const CodeGenOptions& opts,
                            bool recoverMode) {
    std::string source = readFile(inputPath);
    try {
        Lexer lexer(source);
        auto tokens = lexer.tokenize();

        ErrorCollector errors;
        Parser parser(std::move(tokens), recoverMode ? &errors : nullptr);
        auto ast = parser.parse();

        if (recoverMode && errors.hasErrors()) {
            errors.dump(inputPath);
            return false;
        }

        CodeGen gen(opts);
        std::string output = gen.generate(*ast, inputPath);

        if (outputPath.empty()) std::cout << output;
        else if (!writeFile(outputPath, output)) return false;

    } catch (const LexError& e) {
        std::cerr << inputPath << ":" << e.line << ":" << e.col
                  << ": lex error: " << e.what() << "\n";
        return false;
    } catch (const ParseError& e) {
        std::cerr << inputPath << ":" << e.line << ":" << e.col
                  << ": parse error: " << e.what() << "\n";
        return false;
    } catch (const CodeGenError& e) {
        std::cerr << inputPath << ": codegen error: " << e.what() << "\n";
        return false;
    } catch (const std::exception& e) {
        std::cerr << inputPath << ": error: " << e.what() << "\n";
        return false;
    }
    return true;
}

// ---------------------------------------------------------------------------
// main
// ---------------------------------------------------------------------------
int main(int argc, char** argv) {
    std::vector<std::string> positional;
    std::string outputPath;
    std::string outDir;
    bool watchMode   = false;
    bool recoverMode = false;
    unsigned threads = 0;
    CodeGenOptions copts;
    BatchOptions   bopts;
    bopts.verbose = false;
    bopts.noCopy  = false;

    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];

        auto nextArg = [&](const char* flag) -> std::string {
            if (++i >= argc) {
                std::cerr << "error: " << flag << " requires a value\n";
                std::exit(1);
            }
            return argv[i];
        };

        if (arg == "-h" || arg == "--help") {
            printUsage(argv[0]);
            return 0;
        } else if (arg == "-o") {
            outputPath = nextArg("-o");
        } else if (arg == "--out-dir") {
            outDir = nextArg("--out-dir");
        } else if (arg == "--pragma" || arg == "--jsx-pragma") {
            std::string p = nextArg(arg.c_str());
            if      (p == "react") copts.pragma = JSXPragma::React;
            else if (p == "h")     copts.pragma = JSXPragma::H;
            else if (p == "jsx")   copts.pragma = JSXPragma::JSX;
            else if (p == "auto")  copts.pragma = JSXPragma::AutoImport;
            else {
                std::cerr << "error: unknown pragma '" << p
                          << "' (use: react, h, jsx, auto)\n";
                return 1;
            }
        } else if (arg == "--jsx-runtime") {
            std::string r = nextArg("--jsx-runtime");
            if (r == "automatic") copts.pragma = JSXPragma::AutoImport;
            else if (r != "classic") {
                std::cerr << "error: --jsx-runtime must be 'classic' or 'automatic'\n";
                return 1;
            }
        } else if (arg == "--dev") {
            copts.devMode = true;
        } else if (arg == "--no-copy") {
            bopts.noCopy = true;
        } else if (arg == "--verbose") {
            bopts.verbose = true;
        } else if (arg == "--watch") {
            watchMode = true;
        } else if (arg == "--recover") {
            recoverMode = true;
        } else if (arg == "--threads") {
            std::string v = nextArg("--threads");
            try { threads = static_cast<unsigned>(std::stoul(v)); }
            catch (...) {
                std::cerr << "error: --threads requires a positive integer\n";
                return 1;
            }
        } else if (!arg.empty() && arg[0] == '-') {
            std::cerr << "error: unknown option '" << arg << "'\n";
            printUsage(argv[0]);
            return 1;
        } else {
            positional.push_back(arg);
        }
    }

    if (positional.empty()) {
        printUsage(argv[0]);
        return 1;
    }

    // -----------------------------------------------------------------------
    // Determine run mode
    // -----------------------------------------------------------------------

    // Check if the first positional is a directory
    bool firstIsDir = fs::is_directory(positional[0]);

    bool batchMode = !outDir.empty() || firstIsDir;

    if (!batchMode) {
        // ---- Single-file mode ----
        if (positional.size() > 1) {
            std::cerr << "error: multiple input files require --out-dir\n";
            return 1;
        }
        if (watchMode) {
            std::cerr << "error: --watch requires a source directory\n";
            return 1;
        }
        return transpileSingle(positional[0], outputPath, copts, recoverMode) ? 0 : 1;
    }

    // ---- Batch / directory mode ----
    if (outDir.empty()) {
        std::cerr << "error: --out-dir is required for batch/directory mode\n";
        return 1;
    }

    // Create output directory
    {
        std::error_code ec;
        fs::create_directories(outDir, ec);
        if (ec) {
            std::cerr << "error: cannot create output dir '" << outDir
                      << "': " << ec.message() << "\n";
            return 1;
        }
    }

    bopts.codegenOpts = copts;
    bopts.outDir      = outDir;
    bopts.threads     = threads;

    if (firstIsDir) {
        // Single source directory
        bopts.srcDir = positional[0];
        BatchEngine engine(bopts);

        if (bopts.verbose)
            std::cout << "Transpiling " << bopts.srcDir.string()
                      << "  ->  " << bopts.outDir.string() << "\n";

        BatchResult r = engine.run();

        // Print summary
        std::cout << "\n";
        if (bopts.verbose || r.failed > 0) {
            std::cout << "  transpiled : " << r.transpiled << "\n";
            if (!bopts.noCopy)
                std::cout << "  copied     : " << r.copied << "\n";
            if (r.skipped > 0)
                std::cout << "  skipped    : " << r.skipped << "\n";
            if (r.failed > 0) {
                std::cout << "  failed     : " << r.failed << "\n";
                for (const auto& e : r.errors)
                    std::cerr << e.message << "\n";
            }
        }

        if (watchMode) {
            Watcher watcher(engine, bopts.verbose);
            g_watcher = &watcher;
            std::signal(SIGINT,  handleSignal);
            std::signal(SIGTERM, handleSignal);
            watcher.watch(bopts.srcDir);
            g_watcher = nullptr;
        }

        return r.ok() ? 0 : 1;

    } else {
        // Explicit file list with --out-dir
        int failures = 0;

        // Derive a synthetic srcDir as the common parent of all inputs
        // (used only for output path computation)
        fs::path srcDir = fs::path(positional[0]).parent_path();
        bopts.srcDir    = srcDir;
        BatchEngine engine(bopts);

        for (const auto& inp : positional) {
            BatchResult r;
            engine.processFile(fs::path(inp), r);
            for (const auto& e : r.errors) std::cerr << e.message << "\n";
            failures += r.failed;
        }

        if (watchMode) {
            Watcher watcher(engine, bopts.verbose);
            g_watcher = &watcher;
            std::signal(SIGINT,  handleSignal);
            std::signal(SIGTERM, handleSignal);
            watcher.watch(srcDir);
            g_watcher = nullptr;
        }

        return failures > 0 ? 1 : 0;
    }
}

