void CodeGen::genImportDecl(const Node& n) {
    emit("import ");
    if (n.specifiers.empty()) {
        // side-effect import: import "mod";
    } else if (n.specifiers.size() == 1 && n.specifiers[0]->name == "*") {
        // namespace: import * as ns from "mod"
        emit("* as " + n.specifiers[0]->value);
    } else {
        // Separate default specifiers (boolVal=true) from named ones
        bool hasDefault = false;
        bool first = true;
        for (const auto& s : n.specifiers) {
            if (s->boolVal) { // default import
                if (!first) emit(", ");
                emit(s->name);
                hasDefault = true;
                first = false;
            }
        }
        // Collect named specifiers
        std::vector<const Node*> named;
        for (const auto& s : n.specifiers)
            if (!s->boolVal) named.push_back(s.get());

        if (!named.empty()) {
            if (hasDefault) emit(", ");
            emit("{ ");
            bool fn = true;
            for (const auto* s : named) {
                if (!fn) emit(", ");
                fn = false;
                emit(s->name);
                if (!s->value.empty()) emit(" as " + s->value);
            }
            emit(" }");
        }
    }
    if (!n.source.empty()) emit(" from \"" + n.source + "\"");
    emit(";");
}

